    var m = el('span', 'runid-mark');
    var ico = ICONS[name || 'claude'];
    if (ico) m.innerHTML = ico;   // our own asset (src/icons.ts), never wire data
    // Grouped by client, the row's text label is dropped (see runIdentity below) —
    // this is then the row's ONLY per-row indication of which client it is, so it
    // needs its own accessible name instead of relying on icon recognition alone.
    m.title = clientLabel(name, CLIENT_WIRE);
    return m;
  }"
